WITH parsed AS (SELECT id, plan, currency, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE plan != 'pro') SELECT CASE WHEN lowest_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END AS lowest_price_tier, SUM(CASE WHEN currency = 'THB' THEN avg_tier_price ELSE 0 END) AS thb_avg_tier_price, AVG(entry_price) AS avg_entry_price, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE currency = 'EUR') AS eur_rows, ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS entry_price_per_starter FROM parsed GROUP BY CASE WHEN lowest_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING thb_avg_tier_price < 1000000 ORDER BY lowest_price_tier DESC NULLS LAST;
